1398	// or a pre-formatted string (for backwards compat), and scopedFallback is used when scoped parsing fails.
1399	func appendTranscriptSection(sb *strings.Builder, verbose, full bool, fullTranscript, scopedTranscript []byte, scopedFallback string, agentType types.AgentType) {
1400		switch {
1401		case full:
