1409	// formatTranscriptBytes formats transcript bytes into a human-readable string.
1410	// It parses the transcript (JSONL for Claude, JSON for Gemini) and formats it using the condensed format.
1411	// The fallback is used for backwards compatibility when transcript parsing fails or is empty.
1412	func formatTranscriptBytes(transcriptBytes []byte, fallback string, agentType types.AgentType) string {
1413		if len(transcriptBytes) == 0 {
1414			if fallback != "" {
1415				return fallback + "\n"
1416			}
1417			return "  (none)\n"
1418		}
1419	
1420		// transcriptBytes is read from checkpoint storage, which redacts on write.
1421		condensed, err := summarize.BuildCondensedTranscriptFromBytes(redact.AlreadyRedacted(transcriptBytes), agentType)
1422		if err != nil || len(condensed) == 0 {
1423			condensed, err = buildCondensedCompactTranscriptEntries(transcriptBytes)
1424		}
1425		if err != nil || len(condensed) == 0 {
1426			if fallback != "" {
1427				return fallback + "\n"
1428			}
1429			return "  (failed to parse transcript)\n"
1430		}
1431	
1432		input := summarize.Input{Transcript: condensed}
1433		return summarize.FormatCondensedTranscript(input)
1434	}
