1436	func buildCondensedCompactTranscriptEntries(transcriptBytes []byte) ([]summarize.Entry, error) {
1437		compactEntries, err := transcriptcompact.BuildCondensedEntries(transcriptBytes)
1438		if err != nil {
1439			return nil, fmt.Errorf("parsing compact transcript: %w", err)
1440		}
1441	
1442		entries := make([]summarize.Entry, 0, len(compactEntries))
1443		for _, entry := range compactEntries {
1444			switch entry.Type {
1445			case "user":
1446				entries = append(entries, summarize.Entry{Type: summarize.EntryTypeUser, Content: entry.Content})
1447			case "assistant":
1448				entries = append(entries, summarize.Entry{Type: summarize.EntryTypeAssistant, Content: entry.Content})
1449			case "tool":
1450				entries = append(entries, summarize.Entry{Type: summarize.EntryTypeTool, ToolName: entry.ToolName, ToolDetail: entry.ToolDetail})
1451			}
1452		}
1453	
1454		if len(entries) == 0 {
1455			return nil, errors.New("no parseable compact transcript entries")
1456		}
1457	
1458		return entries, nil
1459	}
