1461	// formatCheckpointHeader builds the metadata block above the summary body.
1462	// When color is enabled, values are styled with the shared status palette;
1463	// otherwise the same compact shape is returned as plain text.
1464	func formatCheckpointHeader(
1465		summary *checkpoint.CheckpointSummary,
1466		meta checkpoint.CommittedMetadata,
1467		cpID id.CheckpointID,
1468		commits []associatedCommit,
1469		author checkpoint.Author,
1470		styles statusStyles,
1471	) string {
1472		var sb strings.Builder
1473	
1474		headline := "● Checkpoint " + cpID.String()
1475		if styles.colorEnabled {
1476			bullet := styles.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
1477			key := styles.render(styles.bold, "Checkpoint")
1478			val := styles.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), cpID.String())
1479			headline = bullet + " " + key + " " + val
1480		}
1481		sb.WriteString(headline)
1482		sb.WriteString("\n")
1483	
1484		writeRow := func(label, value string) {
1485			paddedLabel := fmt.Sprintf("%-9s", label)
1486			if styles.colorEnabled {
1487				paddedLabel = styles.render(styles.dim, paddedLabel)
1488			}
1489			fmt.Fprintf(&sb, "  %s%s\n", paddedLabel, value)
1490		}
1491	
1492		writeRow("session", meta.SessionID)
1493		writeRow("created", meta.CreatedAt.Format("2006-01-02 15:04:05"))
1494		if author.Name != "" {
1495			writeRow("author", fmt.Sprintf("%s <%s>", author.Name, author.Email))
1496		}
1497	
1498		tokenUsage := meta.TokenUsage
1499		if tokenUsage == nil && summary != nil {
1500			tokenUsage = summary.TokenUsage
1501		}
1502		if tokenUsage != nil {
1503			total := tokenUsage.InputTokens + tokenUsage.CacheCreationTokens +
1504				tokenUsage.CacheReadTokens + tokenUsage.OutputTokens
1505			tokensVal := formatTokenCount(total)
1506			if styles.colorEnabled {
1507				tokensVal = styles.render(styles.yellow, tokensVal)
1508			}
1509			writeRow("tokens", tokensVal)
1510		}
1511	
1512		switch {
1513		case commits == nil:
1514		case len(commits) == 0:
1515			writeRow("commits", "(none on this branch)")
1516		case len(commits) == 1:
1517			c := commits[0]
1518			writeRow("commits", fmt.Sprintf("%s %s", c.ShortSHA, c.Message))
1519		default:
1520			writeRow("commits", fmt.Sprintf("(%d)", len(commits)))
1521			for _, c := range commits {

1522				fmt.Fprintf(&sb, "           %s %s %s\n",
1523					c.ShortSHA, c.Date.Format("2006-01-02"), c.Message)
1524			}
1525		}
1526	
1527		return sb.String()
1528	}
