1657	// computeReachableFromMain returns a set of commit hashes on the main/default branch's first-parent chain.
1658	// On the default branch itself, returns an empty map (no filtering needed).
1659	// Only first-parent commits are included — commits from side branches merged into main are excluded,
1660	// since those could be feature branch commits that shouldn't be filtered out.
1661	func computeReachableFromMain(ctx context.Context, repo *git.Repository) map[plumbing.Hash]bool {
1662		reachableFromMain := make(map[plumbing.Hash]bool)
1663	
1664		isOnDefault, _ := strategy.IsOnDefaultBranch(repo)
1665		if isOnDefault {
1666			return reachableFromMain // No filtering needed on default branch
1667		}
1668	
1669		// Resolve main branch hash
1670		var mainBranchHash plumbing.Hash
1671		if defaultBranchName := strategy.GetDefaultBranchName(repo); defaultBranchName != "" {
1672			ref, refErr := repo.Reference(plumbing.ReferenceName("refs/heads/"+defaultBranchName), true)
1673			if refErr != nil {
1674				ref, refErr = repo.Reference(plumbing.ReferenceName("refs/remotes/origin/"+defaultBranchName), true)
1675			}
1676			if refErr == nil {
1677				mainBranchHash = ref.Hash()
1678			}
1679		}
1680		if mainBranchHash == plumbing.ZeroHash {
1681			mainBranchHash = strategy.GetMainBranchHash(repo)
1682		}
1683		if mainBranchHash == plumbing.ZeroHash {
1684			return reachableFromMain
1685		}
1686	
1687		// Walk main's first-parent chain to build the set
1688		_ = walkFirstParentCommits(ctx, repo, mainBranchHash, strategy.MaxCommitTraversalDepth, func(c *object.Commit) error { //nolint:errcheck // Best-effort
1689			reachableFromMain[c.Hash] = true
1690			return nil
1691		})
1692	
1693		return reachableFromMain
1694	}
1695	
1696	// walkFirstParentCommits walks the first-parent chain starting from `from`,
1697	// calling fn for each commit. It stops after visiting `limit` commits (0 = no limit).
1698	// This avoids the full DAG traversal that repo.Log() does, which follows ALL parents
1699	// of merge commits and can walk into unrelated branch history (e.g., main's full
1700	// history after merging main into a feature branch).
1701	func walkFirstParentCommits(ctx context.Context, repo *git.Repository, from plumbing.Hash, limit int, fn func(*object.Commit) error) error {
1702		current, err := repo.CommitObject(from)
1703		if err != nil {
1704			return fmt.Errorf("failed to get commit %s: %w", from, err)
1705		}
1706	
1707		for count := 0; limit <= 0 || count < limit; count++ {
1708			if err := ctx.Err(); err != nil {
1709				return err //nolint:wrapcheck // Propagating context cancellation
1710			}
1711			if err := fn(current); err != nil {
1712				if errors.Is(err, errStopIteration) {
1713					return nil
1714				}
1715				return err
