2322	// groupByCheckpointID groups rewind points by their checkpoint ID.
2323	// Returns groups sorted by latest commit timestamp (most recent first).
2324	func groupByCheckpointID(points []strategy.RewindPoint) []checkpointGroup {
2325		if len(points) == 0 {
2326			return nil
2327		}
2328	
2329		// Build map of checkpoint ID -> group
2330		groupMap := make(map[string]*checkpointGroup)
2331		var order []string // Track insertion order for stable iteration
2332	
2333		for _, point := range points {
2334			// Determine the checkpoint ID to use for grouping
2335			cpID := point.CheckpointID.String()
2336			if cpID == "" {
2337				// Temporary checkpoints: group by session ID to preserve per-session prompts
2338				// Use session ID prefix for readability (format: YYYY-MM-DD-uuid)
2339				cpID = point.SessionID
2340				if cpID == "" {
2341					cpID = "temporary" // Fallback if no session ID
2342				}
2343			}
2344	
2345			group, exists := groupMap[cpID]
2346			if !exists {
2347				group = &checkpointGroup{
2348					checkpointID: cpID,
2349					prompt:       point.SessionPrompt,
2350					isTemporary:  !point.IsLogsOnly,
2351					isTask:       point.IsTaskCheckpoint,
2352				}
2353				groupMap[cpID] = group
2354				order = append(order, cpID)
2355			}
2356	
2357			// Short git SHA (7 chars)
2358			gitSHA := point.ID
2359			if len(gitSHA) > 7 {
2360				gitSHA = gitSHA[:7]
2361			}
2362	
2363			group.commits = append(group.commits, commitEntry{
2364				date:    point.Date,
2365				gitSHA:  gitSHA,
2366				message: point.Message,
2367			})
2368	
2369			// Update flags - if any commit is temporary/task, the group is too
2370			if !point.IsLogsOnly {
2371				group.isTemporary = true
2372			}
2373			if point.IsTaskCheckpoint {
2374				group.isTask = true
2375			}
2376			// Update prompt if the group's prompt is empty but this point has one
2377			if group.prompt == "" && point.SessionPrompt != "" {
2378				group.prompt = point.SessionPrompt
2379			}
2380		}
2381	
2382		// Sort commits within each group by date (most recent first)
2383		for _, group := range groupMap {
2384			sort.Slice(group.commits, func(i, j int) bool {
2385				return group.commits[i].date.After(group.commits[j].date)
2386			})
2387		}
2388	
2389		// Build result slice in order, then sort by latest commit
2390		result := make([]checkpointGroup, 0, len(order))
2391		for _, cpID := range order {
2392			result = append(result, *groupMap[cpID])
2393		}
2394	
2395		// Sort groups by latest commit timestamp (most recent first)
2396		sort.Slice(result, func(i, j int) bool {
2397			// Each group's commits are already sorted, so first commit is latest
2398			if len(result[i].commits) == 0 {
2399				return false
2400			}
2401			if len(result[j].commits) == 0 {
2402				return true
2403			}
2404			return result[i].commits[0].date.After(result[j].commits[0].date)
2405		})
2406	
2407		return result
2408	}
