2410	// formatCheckpointGroup formats a single checkpoint group for display.
2411	func formatCheckpointGroup(sb *strings.Builder, group checkpointGroup) {
2412		// Checkpoint ID (truncated for display)
2413		cpID := group.checkpointID
2414		if len(cpID) > checkpointIDDisplayLength {
2415			cpID = cpID[:checkpointIDDisplayLength]
2416		}
2417	
2418		// Build status indicators
2419		// Skip [temporary] indicator when cpID is already "temporary" to avoid redundancy
2420		var indicators []string
2421		if group.isTask {
2422			indicators = append(indicators, "[Task]")
2423		}
2424		if group.isTemporary && cpID != "temporary" {
2425			indicators = append(indicators, "[temporary]")
2426		}
2427	
2428		indicatorStr := ""
2429		if len(indicators) > 0 {
2430			indicatorStr = " " + strings.Join(indicators, " ")
2431		}
2432	
2433		// Prompt (truncated)
2434		var promptStr string
2435		if group.prompt == "" {
2436			promptStr = "(no prompt)"
2437		} else {
2438			// Quote actual prompts
2439			promptStr = fmt.Sprintf("%q", strategy.TruncateDescription(group.prompt, maxPromptDisplayLength))
2440		}
2441	
2442		// Checkpoint header: [checkpoint_id] [indicators] prompt
2443		fmt.Fprintf(sb, "[%s]%s %s\n", cpID, indicatorStr, promptStr)
2444	
2445		// List commits under this checkpoint
2446		for _, commit := range group.commits {
2447			// Format: "  MM-DD HH:MM (git_sha) message"
2448			dateTimeStr := commit.date.Format("01-02 15:04")
2449			message := strategy.TruncateDescription(commit.message, maxMessageDisplayLength)
2450			fmt.Fprintf(sb, "  %s (%s) %s\n", dateTimeStr, commit.gitSHA, message)
2451		}
2452	}
