2486	// hasCodeChanges returns true if the commit has changes to non-metadata files.
2487	// Uses a full tree diff to distinguish code changes from .entire/ metadata-only changes.
2488	// Returns false only if the commit has a parent AND only modified .entire/ metadata files.
2489	//
2490	// WARNING: This is expensive via go-git (resolves many tree/blob objects from packfiles).
2491	// For list views with many checkpoints, use hasAnyChanges instead.
2492	func hasCodeChanges(commit *object.Commit) bool {
2493		// First commit on shadow branch captures working copy state - always meaningful
2494		if commit.NumParents() == 0 {
2495			return true
2496		}
2497	
2498		parent, err := commit.Parent(0)
2499		if err != nil {
2500			return true // Can't check, assume meaningful
2501		}
2502	
2503		commitTree, err := commit.Tree()
2504		if err != nil {
2505			return true
2506		}
2507	
2508		parentTree, err := parent.Tree()
2509		if err != nil {
2510			return true
2511		}
2512	
2513		changes, err := parentTree.Diff(commitTree)
2514		if err != nil {
2515			return true
2516		}
2517	
2518		// Check if any non-metadata file was changed
2519		for _, change := range changes {
2520			name := change.To.Name
2521			if name == "" {
2522				name = change.From.Name
2523			}
2524			// Skip .entire/ metadata files
2525			if !strings.HasPrefix(name, ".entire/") {
2526				return true
2527			}
2528		}
2529	
2530		return false
2531	}
2532	
2533	// hasAnyChanges is a lightweight alternative to hasCodeChanges that compares
2534	// tree hashes without doing a full diff. Returns true if the commit's tree
2535	// differs from its parent's tree. This may include metadata-only changes,
2536	// but is O(1) instead of O(files) — suitable for list views.
2537	func hasAnyChanges(commit *object.Commit) bool {
2538		if commit.NumParents() == 0 {
2539			return true
2540		}
2541		parent, err := commit.Parent(0)
2542		if err != nil {
2543			return true
2544		}
2545		return commit.TreeHash != parent.TreeHash
2546	}

