858	func maybeCompactExternalTranscriptForSummary(ctx context.Context, scopedTranscript []byte, agentType types.AgentType) []byte {
859		if transcriptHasSummaryContent(scopedTranscript, agentType) {
860			return scopedTranscript
861		}
862	
863		ag, err := agent.GetByAgentType(agentType)
864		if err != nil {
865			external.DiscoverAndRegister(ctx)
866			ag, err = agent.GetByAgentType(agentType)
867		}
868		if err != nil || !external.IsExternal(ag) {
869			return scopedTranscript
870		}
871	
872		compactor, ok := agent.AsTranscriptCompactor(ag)
873		if !ok {
874			return scopedTranscript
875		}
876	
877		tmpFile, err := os.CreateTemp("", "entire-summary-transcript-*.jsonl")
878		if err != nil {
879			logging.Debug(ctx, "external summary compaction unavailable",
880				slog.String("agent", string(agentType)),
881				slog.String("error", err.Error()))
882			return scopedTranscript
883		}
884		tmpPath := tmpFile.Name()
885		defer func() {
886			if removeErr := os.Remove(tmpPath); removeErr != nil {
887				logging.Debug(ctx, "failed to remove temporary summary transcript",
888					slog.String("path", tmpPath),
889					slog.String("error", removeErr.Error()))
890			}
891		}()
892	
893		if _, err := tmpFile.Write(scopedTranscript); err != nil {
894			_ = tmpFile.Close()
895			logging.Debug(ctx, "external summary compaction transcript write failed",
896				slog.String("agent", string(agentType)),
897				slog.String("error", err.Error()))
898			return scopedTranscript
899		}
900		if err := tmpFile.Close(); err != nil {
901			logging.Debug(ctx, "external summary compaction transcript close failed",
902				slog.String("agent", string(agentType)),
903				slog.String("error", err.Error()))
904			return scopedTranscript
905		}
906	
907		compacted, err := compactor.CompactTranscript(ctx, tmpPath)
908		if err != nil || compacted == nil || len(compacted.Transcript) == 0 {
909			if err != nil {
910				logging.Debug(ctx, "external summary compaction failed",
911					slog.String("agent", string(agentType)),
912					slog.String("error", err.Error()))
913			}
914			return scopedTranscript
915		}
916	
917		redacted, err := redact.JSONLBytes(compacted.Transcript)
918		if err != nil {
919			logging.Debug(ctx, "external summary compaction redaction failed",
920				slog.String("agent", string(agentType)),
921				slog.String("error", err.Error()))
922			return scopedTranscript
923		}
924		redactedTranscript := redacted.Bytes()
925		if !transcriptHasSummaryContent(redactedTranscript, agentType) {
926			return scopedTranscript
927		}
928	
929		logging.Debug(ctx, "using external compact transcript for summary generation",
930			slog.String("agent", string(agentType)))
931		return redactedTranscript
932	}
