939	// generateCheckpointAISummary returns the generated summary, the effective
940	// deadline applied to the underlying call (which may be shorter than
941	// checkpointSummaryTimeout if the parent context had an earlier deadline),
942	// and any error. The effective deadline is returned so the caller can render
943	// the true timeout value in user-facing error messages instead of always
944	// showing the package default.
945	func generateCheckpointAISummary(ctx context.Context, scopedTranscript []byte, filesTouched []string, agentType types.AgentType, generator summarize.Generator) (*checkpoint.Summary, time.Duration, error) {
946		timeoutCtx, cancel := context.WithTimeout(ctx, checkpointSummaryTimeout)
947		timeoutDuration := checkpointSummaryTimeout
948		if deadline, ok := timeoutCtx.Deadline(); ok {
949			timeoutDuration = time.Until(deadline)
950		}
951		defer cancel()
952	
953		// scopedTranscript is either read from checkpoint storage (redacted on
954		// write) or replaced by external compact output redacted before use.
955		summary, err := generateTranscriptSummary(timeoutCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, agentType, generator)
956		if err != nil {
957			// Only classify as ctx cancel/deadline when the error chain actually
958			// contains the sentinel. Relying on timeoutCtx.Err() here loses typed
959			// errors (e.g. *ClaudeError) when the subprocess returned a real
960			// structured failure while timeoutCtx.Err() is non-nil for any reason
961			// (parent cancelled, deadline already elapsed, etc.).
962			if errors.Is(err, context.Canceled) {
963				return nil, timeoutDuration, fmt.Errorf("summary generation canceled: %w", err)
964			}
965			if errors.Is(err, context.DeadlineExceeded) {
966				return nil, timeoutDuration, fmt.Errorf("summary generation timed out after %s: %w", formatSummaryTimeout(timeoutDuration), err)
967			}
968			return nil, timeoutDuration, err
969		}
970	
971		return summary, timeoutDuration, nil
972	}
