974	// formatCheckpointSummaryError maps typed Claude CLI errors and context
975	// sentinels to user-facing messages.
976	func formatCheckpointSummaryError(err error, deadline time.Duration) error {
977		var claudeErr *claudecode.ClaudeError
978		switch {
979		case errors.As(err, &claudeErr):
980			switch claudeErr.Kind { //nolint:exhaustive // ClaudeErrorUnknown handled by default
981			case claudecode.ClaudeErrorAuth:
982				return fmt.Errorf("Claude authentication failed%s\nRun `claude login` and retry", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005: capitalized because Claude is a proper noun
983			case claudecode.ClaudeErrorRateLimit:
984				return fmt.Errorf("Claude rejected the summary request due to rate limits or quota%s\nWait and retry", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005
985			case claudecode.ClaudeErrorConfig:
986				return fmt.Errorf("Claude rejected the summary request%s\nCheck your Claude CLI config and selected model", formatMessageSuffix(claudeErr.Message)) //nolint:staticcheck // ST1005
987			case claudecode.ClaudeErrorCLIMissing:
988				return errors.New("Claude CLI is not installed or not on PATH") //nolint:staticcheck // ST1005
989			default:
990				return fmt.Errorf("Claude failed to generate the summary%s", formatClaudeErrorSuffix(claudeErr)) //nolint:staticcheck // ST1005
991			}
992		case errors.Is(err, context.DeadlineExceeded):
993			// Deliberately provider-neutral: explain --generate supports multiple
994			// summary providers (claude-code, codex, gemini, ...), so hardcoding
995			// "Claude" / "sonnet" / "Anthropic" here would misdirect users who
996			// selected a different provider in .entire/settings.json.
997			return fmt.Errorf(
998				"summary generation did not return within the %s safety deadline. This usually means one of:\n"+
999					"  - the selected model is taking longer than expected on a large transcript\n"+
1000					"  - the summary provider's CLI cannot reach its API (network, VPN, firewall)\n"+
1001					"    Try: run the provider CLI directly to confirm it works\n"+
1002					"  - the provider's API is degraded",
1003				formatSummaryTimeout(deadline))
1004		case errors.Is(err, context.Canceled):
1005			return errors.New("summary generation canceled")
1006		default:
1007			return fmt.Errorf("failed to generate summary: %w", err)
1008		}
1009	}
