1022	// formatClaudeErrorSuffix builds a diagnostic suffix for user-facing output
1023	// when we fall through to the default "failed to generate the summary" path.
1024	// Prefers the envelope Message, falls back to HTTP status, then exit code,
1025	// so the user never sees a bare "Claude failed to generate the summary:"
1026	// with nothing after the colon (which happens when Claude returns
1027	// is_error:true with result:null, or when the subprocess crashes with no
1028	// stderr output). ExitCode < 0 means the subprocess did not produce a real
1029	// exit code (e.g. launch failure) — render that as "abnormal termination"
1030	// rather than the misleading "exited with code -1".
1031	func formatClaudeErrorSuffix(e *claudecode.ClaudeError) string {
1032		if e.Message != "" {
1033			return ": " + e.Message
1034		}
1035		switch {
1036		case e.APIStatus != 0:
1037			return fmt.Sprintf(" (Anthropic API returned HTTP %d)", e.APIStatus)
1038		case e.ExitCode > 0:
1039			return fmt.Sprintf(" (claude CLI exited with code %d)", e.ExitCode)
1040		case e.ExitCode < 0:
1041			return " (claude CLI terminated abnormally — no exit code captured)"
1042		default:
1043			return " (no diagnostic detail available from Claude CLI)"
1044		}
1045	}
